const V2FunctionSpec *v2_lookup_function_spec(const char *fn) {
  if (fn == NULL || fn[0] == '\0') {
    return NULL;
  }

  const size_t nameCount = sizeof(V2_FUNCTION_NAME_MAP) / sizeof(V2_FUNCTION_NAME_MAP[0]);
  for (size_t i = 0; i < nameCount; i++) {
    const V2FunctionNameMapEntry entry = V2_FUNCTION_NAME_MAP[i];
    if (strcmp(fn, entry.name) == 0) {
      return &V2_FUNCTION_SPECS[entry.specIndex];
    }
  }

  return NULL;
}

